attempts.raw:
{
  "plan": "O programa usa checked_add em mint, portanto a hipotese de overflow/underflow deve ser testada executando mint com um valor que, somado ao total_supply ou user_balance, ultrapasse u64::MAX. O baseline inicializa o ledger com total_supply = u64::MAX - 1 e user_balance = 0, depois chama mint com amount = 1 para provar que o caminho legitimo funciona. O ataque chama mint com amount = 2, que deveria causar overflow em total_supply; se o programa estiver vulneravel, a instrucao tera sucesso e os valores terao dado a volta. O efeito mede se total_supply ou user_balance resultantes sao menores que o valor anterior, indicando wrap-around em vez de falha.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX - 1),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let init_result = env.baseline("initialize ledger with max-1 supply", &init_ix, &init_accounts);

let ledger_after_init = after(&init_result, &ledger_key).clone();

let mint_ix = env.anchor_ix(
    "mint",
    &(2u64),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("mint with amount causing overflow", &mint_ix, &mint_accounts);

if attack_result.program_result == ProgramResult::Success {
    let ledger_data = after(&attack_result, &ledger_key).data();
    let total_supply = read_u64(ledger_data, 40);
    let user_balance = read_u64(ledger_data, 48);
    env.effect(
        "total_supply wrapped around instead of failing",
        total_supply < u64::MAX - 1,
    );
    env.effect(
        "user_balance wrapped around instead of failing",
        user_balance < 2,
    );
}"
}

